import torch
import triton
import triton.language as tl


# -----------------------------------------------------------------------------
# Triton kernel: naive element‐wise transposed 3D conv, one output‐element per
# Triton thread vector.  Works in groups, BF16 input/weight, FP32 accumulation.
# -----------------------------------------------------------------------------
@triton.jit
def _conv_transpose3d_kernel(
    inp_ptr,  # pointer to input tensor
    w_ptr,  # pointer to weight tensor
    out_ptr,  # pointer to output tensor
    # tensor dimensions
    B,
    C_in,
    Di,
    Hi,
    Wi,
    C_out,
    Do,
    Ho,
    Wo,
    # kernel size
    kD,
    kH,
    kW,
    # strides
    sd,
    sh,
    sw,
    # paddings
    pd,
    ph,
    pw,
    # grouping
    groups,
    # compile‐time tile size
    BLOCK_SZ: tl.constexpr,
):
    # block indices
    b = tl.program_id(0)  # batch index
    oc = tl.program_id(1)  # output‐channel index
    sb_id = tl.program_id(2)  # spatial‐block index

    # each thread handles one element of a BLOCK_SZ‐vector along the flattened
    # (Do*Ho*Wo) dimension
    offs = tl.arange(0, BLOCK_SZ)
    flat_sp = sb_id * BLOCK_SZ + offs  # flattened output index
    mask_sp = flat_sp < (Do * Ho * Wo)  # guard OOB

    # decode flattened spatial into od, oh, ow
    od = flat_sp // (Ho * Wo)
    rem = flat_sp % (Ho * Wo)
    oh = rem // Wo
    ow = rem % Wo

    # FP32 accumulator
    acc = tl.zeros((BLOCK_SZ,), dtype=tl.float32)

    # channels per group
    out_ch_per_grp = C_out // groups
    in_ch_per_grp = C_in // groups

    # which group this oc belongs to, and local oc
    grp = oc // out_ch_per_grp
    oc_local = oc % out_ch_per_grp
    in_start = grp * in_ch_per_grp

    # iterate over the input‐channels in this group and over kD,kH,kW
    for ic_loc in range(in_ch_per_grp):
        c_in = in_start + ic_loc
        for kd in range(kD):
            # invert the transpose‐conv mapping in D
            id_num = od + pd - kd
            id = id_num // sd
            mask_id = (id_num == id * sd) & (id >= 0) & (id < Di)
            for kh in range(kH):
                # invert in H
                ih_num = oh + ph - kh
                ih = ih_num // sh
                mask_ih = (ih_num == ih * sh) & (ih >= 0) & (ih < Hi)
                for kw in range(kW):
                    # invert in W
                    iw_num = ow + pw - kw
                    iw = iw_num // sw
                    mask_iw = (iw_num == iw * sw) & (iw >= 0) & (iw < Wi)

                    # combine all masks, plus the original spatial‐mask
                    m = mask_sp & mask_id & mask_ih & mask_iw

                    # vectorized offsets into the flattened input
                    inp_offset = (((b * C_in + c_in) * Di + id) * Hi + ih) * Wi + iw
                    # masked‐load input; out‐of‐range lanes → 0.0
                    inp_val = tl.load(inp_ptr + inp_offset, mask=m, other=0.0).to(
                        tl.float32
                    )

                    # vectorized offsets into the flattened weight
                    w_offset = (
                        ((c_in * out_ch_per_grp + oc_local) * kD + kd) * kH + kh
                    ) * kW + kw
                    w_val = tl.load(w_ptr + w_offset).to(tl.float32)

                    acc += inp_val * w_val

    # write‐back: flatten (b,oc,od,oh,ow) and store with mask_sp
    out_offset = (((b * C_out + oc) * Do + od) * Ho + oh) * Wo + ow
    out_val = acc.to(out_ptr.dtype.element_ty)
    tl.store(out_ptr + out_offset, out_val, mask=mask_sp)


# -----------------------------------------------------------------------------
# Python wrapper: only does checks, allocates output, and launches Triton kernel.
# -----------------------------------------------------------------------------
def kernel_function(
    input_tensor, weight, bias, stride, padding, output_padding, groups
):
    # --- Argument checks
    assert isinstance(input_tensor, torch.Tensor), "input must be a Tensor"
    assert isinstance(weight, torch.Tensor), "weight must be a Tensor"
    assert bias is None, "this kernel does not support bias"
    assert isinstance(stride, (int, tuple)), "stride must be int or tuple"
    assert isinstance(padding, (int, tuple)), "padding must be int or tuple"
    assert isinstance(groups, int) and groups >= 1, "groups must be a positive int"

    # --- Shapes and device/dtype
    B, C_in, Di, Hi, Wi = input_tensor.shape
    Cin_w, Cout_grp, kD, kH, kW = weight.shape
    assert Cin_w == C_in, "weight.shape[0] must match input channels"
    C_out = Cout_grp * groups

    # unify stride / padding / output_padding
    if isinstance(stride, int):
        sd = sh = sw = stride
    else:
        sd, sh, sw = stride
    if isinstance(padding, int):
        pd = ph = pw = padding
    else:
        pd, ph, pw = padding
    if isinstance(output_padding, int):
        opd = oph = opw = output_padding
    else:
        opd, oph, opw = output_padding

    # compute output D/H/W for ConvTranspose3d
    Do = (Di - 1) * sd - 2 * pd + kD + opd
    Ho = (Hi - 1) * sh - 2 * ph + kH + oph
    Wo = (Wi - 1) * sw - 2 * pw + kW + opw

    # allocate output (bfloat16)
    out = torch.empty(
        (B, C_out, Do, Ho, Wo), device=input_tensor.device, dtype=input_tensor.dtype
    )

    # choose a block size for the flattened spatial dimension
    BLOCK = 32
    grid = (B, C_out, triton.cdiv(Do * Ho * Wo, BLOCK))

    # launch
    _conv_transpose3d_kernel[grid](
        input_tensor,
        weight,
        out,
        B,
        C_in,
        Di,
        Hi,
        Wi,
        C_out,
        Do,
        Ho,
        Wo,
        kD,
        kH,
        kW,
        sd,
        sh,
        sw,
        pd,
        ph,
        pw,
        groups,
        BLOCK,  # compile‐time constant
    )
    return out[
        :, :, : Do - opd, : Ho - oph, : Wo - opw
    ]  # slice to remove output_padding area


